mkitem!{mkimpl!{impl Barrier { # [doc = " Creates a new barrier that can block a given number of threads."] # [doc = ""] # [doc = " A barrier will block `n`-1 threads which call [`wait()`] and then wake"] # [doc = " up all threads at once when the `n`th thread calls [`wait()`]."] # [doc = ""] # [doc = " [`wait()`]: Barrier::wait"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::sync::Barrier;"] # [doc = ""] # [doc = " let barrier = Barrier::new(10);"] # [doc = " ```"] # [stable (feature = "rust1" , since = "1.0.0")] # [rustc_const_stable (feature = "const_barrier" , since = "1.78.0")] # [must_use] # [inline] pub const fn new (n : usize) -> Barrier { Barrier { lock : Mutex :: new (BarrierState { count : 0 , generation_id : 0 }) , cvar : Condvar :: new () , num_threads : n , } } # [doc = " Blocks the current thread until all threads have rendezvoused here."] # [doc = ""] # [doc = " Barriers are re-usable after all threads have rendezvoused once, and can"] # [doc = " be used continuously."] # [doc = ""] # [doc = " A single (arbitrary) thread will receive a [`BarrierWaitResult`] that"] # [doc = " returns `true` from [`BarrierWaitResult::is_leader()`] when returning"] # [doc = " from this function, and all other threads will receive a result that"] # [doc = " will return `false` from [`BarrierWaitResult::is_leader()`]."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::sync::Barrier;"] # [doc = " use std::thread;"] # [doc = ""] # [doc = " let n = 10;"] # [doc = " let barrier = Barrier::new(n);"] # [doc = " thread::scope(|s| {"] # [doc = "     for _ in 0..n {"] # [doc = "         // The same messages will be printed together."] # [doc = "         // You will NOT see any interleaving."] # [doc = "         s.spawn(|| {"] # [doc = "             println!(\"before wait\");"] # [doc = "             barrier.wait();"] # [doc = "             println!(\"after wait\");"] # [doc = "         });"] # [doc = "     }"] # [doc = " });"] # [doc = " ```"] # [stable (feature = "rust1" , since = "1.0.0")] pub fn wait (& self) -> BarrierWaitResult { let mut lock = self . lock . lock () ; let local_gen = lock . generation_id ; lock . count += 1 ; if lock . count < self . num_threads { let _guard = self . cvar . wait_while (lock , | state | local_gen == state . generation_id) ; BarrierWaitResult (false) } else { lock . count = 0 ; lock . generation_id = lock . generation_id . wrapping_add (1) ; self . cvar . notify_all () ; BarrierWaitResult (true) } } }}}
